sheet = 'W0::Transition probabilities'
rows = data_rows(sheet, {'G': 'number', 'H': 'string', 'I': 'string'})
transitions = {}
for r in rows:
    p = num(sheet, f'G{r}')
    f = label(sheet, f'H{r}')
    t = label(sheet, f'I{r}')
    transitions[(f, t)] = p
states = ['Idle', 'Active', 'Done']
# step 0: Idle=1, others=0
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}
for step in range(4):
    new_dist = {'Idle': 0.0, 'Active': 0.0, 'Done': 0.0}
    for f in states:
        for t in states:
            p = transitions.get((f, t), 0.0)
            new_dist[t] += dist[f] * p
    dist = new_dist
result = round(dist['Done'], 6)

